/**
 * @summary Attach an assignment document
 */
export const attachAssignmentDocument = (
	assignmentId: string,
	attachAssignmentDocumentBody: BodyType<AttachAssignmentDocumentBody>,
	options?: SecondParameter<typeof customInstance>,
	signal?: AbortSignal,
) => {
	const formData = new FormData();
	if (attachAssignmentDocumentBody.file !== undefined) {
		formData.append(`file`, attachAssignmentDocumentBody.file);
	}

	if (attachAssignmentDocumentBody.category !== undefined) {
		formData.append(`category`, attachAssignmentDocumentBody.category);
	}

	if (attachAssignmentDocumentBody.documentDate !== undefined) {
		formData.append(`documentDate`, attachAssignmentDocumentBody.documentDate);
	}

	if (attachAssignmentDocumentBody.validUntil !== undefined) {
		formData.append(`validUntil`, attachAssignmentDocumentBody.validUntil);
	}

	if (attachAssignmentDocumentBody.note !== undefined) {
		formData.append(`note`, attachAssignmentDocumentBody.note);
	}

	return customInstance<AssignmentDocumentAttached>(
		{
			url: `/api/assignments/${assignmentId}/documents`,
			method: "POST",
			headers: { "Content-Type": "multipart/form-data" },
			data: formData,
			signal,
		},
		options,
	);
};

